/* Fleet text-size setting (design.md "Layout" -> "Text size",
 * fleet-config#967).
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * the per-app part is the `app` prefix the caller passes in.
 *
 * The control is a range-tab row of three buttons carrying
 * data-textsize="small|default|large" (text-size.html). bindTextSize() marks
 * the stored step active and, on a click, persists it to `<app>.textsize`,
 * stamps html[data-textsize] and repaints the row. The pre-paint stamp on
 * load is the boot script's job (text-size-boot.html); binding stamps too, so
 * a page without the boot script still converges on the stored step.
 */

'use strict';

/** The three steps, in control order. */
export const TEXT_SIZES = ['small', 'default', 'large'];

function storageKey(app) {
  return app + '.textsize';
}

/**
 * The stored step for an app, or 'default' when unset, unknown or unreadable.
 *
 * @param {string} app  the app's localStorage prefix (e.g. 'app-launcher').
 * @returns {string}
 */
export function readTextSize(app) {
  let value = null;
  try {
    value = localStorage.getItem(storageKey(app));
  } catch (e) {
    // Storage blocked (private mode, cleared site data): use the default.
  }
  return TEXT_SIZES.includes(value) ? value : 'default';
}

/**
 * Stamp a step on the root element; text-size.css maps it to a font-size.
 *
 * @param {string} size  one of TEXT_SIZES.
 */
export function applyTextSize(size) {
  document.documentElement.dataset.textsize = size;
}

/**
 * Wire a text-size control and paint the stored step.
 *
 * @param {HTMLElement} group  the row holding the [data-textsize] buttons.
 * @param {string} app         the app's localStorage prefix.
 */
export function bindTextSize(group, app) {
  const buttons = Array.from(group.querySelectorAll('[data-textsize]'));
  const paint = (size) => {
    buttons.forEach((btn) => {
      const on = btn.dataset.textsize === size;
      btn.classList.toggle('active', on);
      btn.setAttribute('aria-pressed', String(on));
    });
  };
  const current = readTextSize(app);
  applyTextSize(current);
  paint(current);
  group.addEventListener('click', (event) => {
    const btn = event.target.closest('[data-textsize]');
    if (!btn || !group.contains(btn) || !TEXT_SIZES.includes(btn.dataset.textsize)) return;
    const size = btn.dataset.textsize;
    try {
      localStorage.setItem(storageKey(app), size);
    } catch (e) {
      // Not persisted; the step still applies for this page view.
    }
    applyTextSize(size);
    paint(size);
  });
}
